ruleExplore.bookList:
@js:
(function(){
  var cat = '';
  try {
    var bu = String(baseUrl || '');
    if (bu.indexOf('##') >= 0) {
      cat = decodeURIComponent(bu.split('##')[1]);
    }
  } catch(e){}
  var d = JSON.parse(result);
  var secs = (d && d.sections) || [];
  var books = [];
  if (cat) {
    for (var i=0;i<secs.length;i++){
      if (secs[i] && secs[i].label === cat) { books = secs[i].books || []; break; }
    }
  } else {
    books = (d && d.books) || [];
  }
  return books;
})()

ruleToc.chapterList:
@js:
(function(){
  var out = [];
  try {
    var d = JSON.parse(result);
    var arr = d.chapters || [];
    for (var i=0;i<arr.length;i++){
      var it = arr[i] || {};
      var id = String(it.id || '');
      if (!id) continue;
      out.push({
        name: it.title || '',
        url: id
      });
    }
  } catch(e) {
    out = [];
  }
  return out;
})()
